        private readonly Desktop desktop;private WindowEntry target;private readonly TextBox input;private readonly TextBlock answer,destination;private readonly Button confirm,microphone;private Action pending;private SpeechRecognitionEngine recognizer;private SpeechSynthesizer speaker;private readonly DispatcherTimer listening=new DispatcherTimer{Interval=TimeSpan.FromSeconds(12)},appearance=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(820)},completion=new DispatcherTimer{Interval=TimeSpan.FromSeconds(5.2)};private bool closed,busy;private int operation;internal Func<WindowEntry,Task<string>> ReadPage=BrowserVisibleText.Read;
        private readonly Button send;private readonly TextBlock status;private readonly AssistantVisual visual;private readonly WrapPanel suggestions;private readonly System.Collections.Generic.List<string> history=new System.Collections.Generic.List<string>();private int historyIndex;private string draft="";
        internal IGeminiBrowser Gemini;private System.Threading.CancellationTokenSource query;
        internal AssistantWindow(Desktop controller,WindowEntry source)
        {
            desktop=controller;Gemini=new GeminiBrowser(()=>LocalCommands.ChromePath(desktop.Apps));target=source;Title="MacFlow · Asistente";Width=460;Height=382;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;ShowInTaskbar=false;Topmost=true;Background=Brushes.Transparent;
            Resources["GlassWidgetSurface"]="Dark";Resources["GlassInk"]=Brushes.White;Resources["GlassMuted"]=Design.Brush("#A7A7B0");Resources["FieldBrush"]=Design.Brush("#18FFFFFF");
            var root=new DockPanel();var header=new DockPanel{Margin=new Thickness(0,0,0,18)};
            var close=ActionButton("×",delegate{StopAllVoice();Design.Dismiss(this);});close.Width=30;close.ToolTip="Cerrar asistente · Esc";System.Windows.Automation.AutomationProperties.SetName(close,"Cerrar asistente");DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);
            visual=new AssistantVisual{Width=42,Height=42,Margin=new Thickness(0,0,12,0)};DockPanel.SetDock(visual,Dock.Left);header.Children.Add(visual);
            var name=new StackPanel{VerticalAlignment=VerticalAlignment.Center};name.Children.Add(Design.Text("MacFlow",18,true));status=Design.Text("Listo para ayudarte",11,false);status.Foreground=Design.Brush("#A7A7B0");status.Margin=new Thickness(0,4,0,0);name.Children.Add(status);header.Children.Add(name);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
            var footer=new StackPanel();destination=Design.Text("",11,false);destination.TextTrimming=TextTrimming.CharacterEllipsis;destination.Margin=new Thickness(0,8,0,8);footer.Children.Add(destination);
            var row=new DockPanel();send=ActionButton("↑",async delegate{await Execute(input.Text);});send.FontSize=23;send.Width=40;send.Background=Brushes.White;send.Foreground=Brushes.Black;send.Margin=new Thickness(8,0,0,0);send.ToolTip="Enviar · Enter";System.Windows.Automation.AutomationProperties.SetName(send,"Enviar orden");DockPanel.SetDock(send,Dock.Right);row.Children.Add(send);
            input=new TextBox{FontSize=15,Padding=new Thickness(12,10,12,10),MaxLength=4000,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Foreground=Brushes.White,CaretBrush=Brushes.White,VerticalContentAlignment=VerticalAlignment.Center};System.Windows.Automation.AutomationProperties.SetName(input,"Orden para MacFlow");var field=new Grid();field.Children.Add(input);var placeholder=Design.Text("Preguntá o pedí una acción…",14,false);placeholder.Foreground=Design.Brush("#91919C");placeholder.Margin=new Thickness(12,0,12,0);placeholder.IsHitTestVisible=false;field.Children.Add(placeholder);input.TextChanged+=delegate{placeholder.Visibility=input.Text.Length==0?Visibility.Visible:Visibility.Collapsed;};row.Children.Add(new Border{Background=Design.Brush("#18FFFFFF"),CornerRadius=new CornerRadius(18),Child=field});footer.Children.Add(row);
            var actions=new WrapPanel{Margin=new Thickness(0,9,0,0)};microphone=ActionButton("Hablar",Listen);actions.Children.Add(microphone);actions.Children.Add(ActionButton("Detener",delegate{StopAllVoice();answer.Text="Operación detenida.";UpdateState();}));actions.Children.Add(ActionButton("Leer respuesta",delegate{Speak(answer.Text);}));actions.Children.Add(ActionButton("Copiar",delegate{try{Clipboard.SetText(answer.Text);}catch{status.Text="No se pudo copiar";}}));footer.Children.Add(actions);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
            var content=new StackPanel();answer=Design.Text("¿Qué necesitás hacer?",21,true);answer.TextWrapping=TextWrapping.Wrap;answer.Margin=new Thickness(0,0,0,14);content.Children.Add(answer);
            suggestions=new WrapPanel();foreach(string command in new[]{"Abrí Chrome","Minimizá esta ventana","Leeme","Centro de control","Gemini"}){string selected=command;suggestions.Children.Add(ActionButton(command,delegate{input.Text=selected;input.Focus();input.CaretIndex=input.Text.Length;}));}content.Children.Add(suggestions);
            var hint=Design.Text("Preguntas → Gemini en Chrome · acciones → tu equipo",11,false);hint.Foreground=Design.Brush("#A7A7B0");hint.Margin=new Thickness(0,10,0,0);content.Children.Add(hint);
