            input.PreviewKeyDown+=delegate(object s,KeyEventArgs e){if(e.Key!=Key.Up&&e.Key!=Key.Down||history.Count==0)return;if(historyIndex==history.Count)draft=input.Text;historyIndex=Math.Max(0,Math.Min(history.Count,historyIndex+(e.Key==Key.Up?-1:1)));input.Text=historyIndex==history.Count?draft:history[historyIndex];input.CaretIndex=input.Text.Length;e.Handled=true;};
            KeyDown+=async delegate(object s,KeyEventArgs e){if(e.Key==Key.Enter){e.Handled=true;if(pending==null)await Execute(input.Text);}else if(e.Key==Key.Escape){e.Handled=true;StopAllVoice();Design.Dismiss(this);}};
