        }
        internal void BeginFromIsland(){if(closed)return;StopAllVoice();pending=null;confirm.Visibility=Visibility.Collapsed;Hide();desktop.SetAssistantVisual(AssistantStage.Appearance,"");SoundCue.Play("open");appearance.Stop();appearance.Start();}
        private static Button ActionButton(string label,Action action){var button=Design.Button(label,action,false);button.Foreground=Brushes.White;button.Background=Design.Brush("#12FFFFFF");button.FontSize=12;button.Padding=new Thickness(10,6,10,6);return button;}
        private void UpdateState(){if(closed)return;send.IsEnabled=!busy;status.Text=busy?"Trabajando…":desktop.AssistantListening?"Te escucho…":pending!=null?"Necesito tu confirmación":"Listo para ayudarte";visual.Set(busy?AssistantStage.Working:desktop.AssistantListening?AssistantStage.Listening:AssistantStage.Answer);}
        private void PlaceUnderIsland(){var bar=desktop.ActivityBar;var area=DisplaySpace.For(bar);Width=Math.Min(460,area.Width-24);Height=Math.Min(382,area.Height-110);DisplaySpace.Place(this,area,(area.Width-Width)/2,82);}
        internal void ShowInput(){if(closed)return;appearance.Stop();StopListening();if(!IsVisible){PlaceUnderIsland();Show();Motion.Fade(this,0,1,200);}UpdateState();desktop.UpdateVoiceWake();desktop.UpdateAssistantEdge();if(!desktop.IsTesting){Activate();input.Focus();}}
        internal void SetTarget(WindowEntry source){target=source;destination.Text=source==null?"Para escribir o leer Chrome, abrí el asistente desde la barra con esa ventana activa.":"Ventana elegida: "+source.Title;}
        private void Say(string text){answer.Text=text;answer.FontSize=15;answer.FontWeight=FontWeights.Normal;desktop.SetAssistantVisual(AssistantStage.Answer,text);visual.Set(AssistantStage.Answer);completion.Stop();completion.Start();if(!desktop.IsTesting)SoundCue.Play("done");}
        internal async Task Execute(string command)
        {
            if(closed||busy||String.IsNullOrWhiteSpace(command))return;command=command.Trim();if(history.Count==0||history[history.Count-1]!=command){history.Add(command);if(history.Count>12)history.RemoveAt(0);}historyIndex=history.Count;draft="";StopVoice();StopListening();pending=null;confirm.Visibility=Visibility.Collapsed;var request=LocalCommands.Parse(command);int token=++operation;busy=true;completion.Stop();suggestions.Visibility=Visibility.Collapsed;desktop.SetAssistantVisual(AssistantStage.Working,"Procesando la orden…");UpdateState();
            try
            {
                if(request.Intent==LocalIntent.Open){if(LocalCommands.Normalize(request.Argument)=="gemini"){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),new Uri("https://gemini.google.com/app"));Say("Gemini abierto en Chrome. Iniciá sesión si lo solicita.");return;}var key=LocalCommands.Normalize(request.Argument);var candidates=desktop.Apps.Where(a=>LocalCommands.Normalize(a.Name).Contains(key)).ToArray();var exact=candidates.FirstOrDefault(a=>LocalCommands.Normalize(a.Name)==key);if(exact!=null)candidates=new[]{exact};if(candidates.Length!=1){Say(candidates.Length==0?"No encontré esa aplicación. Probá su nombre completo.":"Hay varias coincidencias: "+String.Join(", ",candidates.Select(a=>a.Name))+". Usá el nombre completo.");return;}desktop.Launch(candidates[0]);Say("Abriendo "+candidates[0].Name+".");}
                else if(request.Intent==LocalIntent.Search){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),LocalCommands.SearchUri(request.Argument));Say("Búsqueda abierta en Chrome. Cuando esté lista, reabrí el asistente desde la barra y pedí Leeme. La disponibilidad del resumen de IA depende de Google.");}
                else if(request.Intent==LocalIntent.Gemini&&String.IsNullOrWhiteSpace(request.Argument)){LocalCommands.OpenChrome(LocalCommands.ChromePath(desktop.Apps),new Uri("https://gemini.google.com/app"));Say("Gemini abierto en Chrome. Podés preguntarme directamente desde acá.");}
                else if(request.Intent==LocalIntent.Write){if(!Native.Matches(target)){Say("Primero elegí la ventana de destino abriendo el asistente desde la barra.");return;}var chosen=target;string text=request.Argument;answer.Text="Escribir en "+chosen.Title+":\n"+text;Confirm(async delegate{bool ok=await LocalTextInput.Write(chosen,text);if(!closed)Say(ok?"Texto enviado a la ventana elegida.":"No pude escribir: Windows bloqueó la entrada o cambió la ventana activa.");});}
                else if(request.Intent==LocalIntent.Minimize||request.Intent==LocalIntent.Close){var key=LocalCommands.Normalize(request.Argument);var windows=desktop.Windows.Where(w=>Native.Matches(w)&&(key=="ventana"||key=="esta ventana"?target!=null&&w.Handle==target.Handle:LocalCommands.Normalize(w.Title+" "+Path.GetFileNameWithoutExtension(w.Executable??"")).Contains(key))).ToArray();if(windows.Length!=1){Say("Elegí una ventana con su nombre completo. Encontré "+windows.Length+" coincidencias.");return;}var chosen=windows[0];if(request.Intent==LocalIntent.Minimize){Say(desktop.MinimizeWindow(chosen)?"Minimizando la ventana.":"Windows no permitió minimizar esa ventana.");}else{answer.Text="¿Cerrar "+chosen.Title+"? La app puede pedirte guardar cambios.";Confirm(delegate{Say(desktop.CloseWindow(chosen)?"Cierre solicitado a la aplicación.":"Windows no permitió cerrar esa ventana.");});}}
                else if(request.Intent==LocalIntent.Read){answer.Text="Leyendo el texto accesible de Chrome…";desktop.SetAssistantVisual(AssistantStage.Working,answer.Text);string text=await ReadPage(target);if(!closed&&token==operation){Say(text);Speak(text);}}
                else if(request.Intent==LocalIntent.Control)desktop.OpenControl();else if(request.Intent==LocalIntent.Settings)desktop.OpenSettings();else if(request.Intent==LocalIntent.Tasks)desktop.OpenTaskManager();
                else if(request.Intent==LocalIntent.VolumeUp||request.Intent==LocalIntent.VolumeDown){using(var backend=new ControlBackend()){var state=backend.Sound();if(!state.Available)throw new IOException("No hay salida de audio.");double value=Math.Max(0,Math.Min(100,state.Volume+(request.Intent==LocalIntent.VolumeUp?10:-10)));backend.Volume(value);Say("Volumen · "+(int)value+"%.");}}
                else
                {
                    query=new System.Threading.CancellationTokenSource();var currentQuery=query;
                    try{string response=await Gemini.Ask(request.Intent==LocalIntent.Gemini?request.Argument:command,currentQuery.Token,delegate(string progress){if(!closed&&token==operation){status.Text=progress;answer.Text=progress;desktop.SetAssistantVisual(AssistantStage.Working,progress);}});if(!closed&&token==operation){Say(response);ShowInput();Speak(response);}}
                    finally{if(query==currentQuery)query=null;currentQuery.Dispose();}
                }
            }catch(OperationCanceledException){if(!closed&&token==operation)Say("Consulta detenida. Si ya se había enviado, permanece en Gemini.");}catch(Exception ex){if(!closed&&token==operation){Say(ex.Message);ShowInput();}}finally{if(token==operation){busy=false;if(!closed&&desktop.AssistantMode==AssistantStage.Working)Say("Listo.");UpdateState();}}
        }
        private void Confirm(Action action){pending=action;confirm.Visibility=Visibility.Visible;desktop.SetAssistantVisual(AssistantStage.Answer,"Revisá y confirmá la acción.");ShowInput();}
        private void Speak(string text){if(String.IsNullOrWhiteSpace(text)||desktop.IsTesting)return;try{if(speaker==null){speaker=new SpeechSynthesizer();speaker.StateChanged+=delegate(object s,System.Speech.Synthesis.StateChangedEventArgs e){if(!closed&&!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(delegate{if(!closed)desktop.SetAssistantSpeaking(speaker.State==SynthesizerState.Speaking&&desktop.AssistantMode!=AssistantStage.Hidden);}));};var voice=speaker.GetInstalledVoices().FirstOrDefault(v=>v.Enabled&&v.VoiceInfo.Culture.TwoLetterISOLanguageName=="es");if(voice!=null)speaker.SelectVoice(voice.VoiceInfo.Name);}speaker.SpeakAsyncCancelAll();speaker.SpeakAsync(text.Substring(0,Math.Min(6000,text.Length)));}catch(Exception ex){answer.Text="La voz de Windows no está disponible: "+ex.Message;}}
        private void Listen()
        {
            if(desktop.IsTesting)return;if(listening.IsEnabled){StopListening();desktop.SetAssistantVisual(AssistantStage.Hidden,null);return;}try{if(recognizer==null){var info=SpeechRecognitionEngine.InstalledRecognizers().FirstOrDefault(r=>r.Culture.TwoLetterISOLanguageName=="es");if(info==null)throw new IOException("No hay reconocimiento de voz español instalado. Podés seguir usando órdenes escritas.");recognizer=new SpeechRecognitionEngine(info);recognizer.LoadGrammar(new DictationGrammar());recognizer.SetInputToDefaultAudioDevice();recognizer.SpeechRecognized+=delegate(object s,SpeechRecognizedEventArgs e){Dispatcher.BeginInvoke(new Action(async delegate{if(closed||!listening.IsEnabled)return;StopListening();input.Text=e.Result.Text;if(e.Result.Confidence>=.65)await Execute(input.Text);else{Say("Revisá la orden reconocida y pulsá Enviar.");ShowInput();}}));};}StopVoice();completion.Stop();recognizer.RecognizeAsync(RecognizeMode.Single);microphone.Content="Escuchando · detener";listening.Start();desktop.SetAssistantListening(true);}catch(Exception ex){StopListening();Say(ex.Message);ShowInput();}
        }
        private void StopListening(){listening.Stop();desktop.SetAssistantListening(false);if(recognizer!=null)try{recognizer.RecognizeAsyncCancel();}catch{}microphone.Content="Hablar";}
        private void StopVoice(){if(speaker!=null)speaker.SpeakAsyncCancelAll();desktop.SetAssistantSpeaking(false);}
        internal void StopAllVoice(){++operation;if(query!=null)query.Cancel();busy=false;pending=null;confirm.Visibility=Visibility.Collapsed;appearance.Stop();completion.Stop();StopListening();StopVoice();desktop.SetAssistantVisual(AssistantStage.Hidden,null);UpdateState();}
